  .gws-plugins-horizon-explore__horizon-card,
  .Zb211,
  .BK6O2d,
  .dG2Xeb,
  .Ep22eb,
  .o6922b,
  /* Voice Search, Lens, and Search-by-image inside Search Box */
  .d6fd2,
  .nh256c,
  .AaV20a,
  .Xb4S1,
  .M8282e,
  .ExT2d,
  [aria-label="Search by voice"],
  [aria-label="Search by image"],
  [aria-label="Google Lens"],
  [aria-label="Google apps"],
  .gb_A,
  .gb_Da,
  .gb_e,
  .gb_2,
  .gb_d,
  /* Header icons & Modern elements */
  .gb_Jd,
  .gb_Xa,
  .gb_Kc,
  .gb_Ea,
  .gb_Za,
  /* Search suggestions & Discover cards */
  .aajZCb,
  .uuB2ed,
  .realbox-icon,
  /* Floating elements, modern widgets & chips */
  .e2213b,
  .K2221b,
  .E2221b,
  .L2221b,
  .R3221b,
  .S3221b,
  .f6612b,
  .O2221b,
  .P2221b,
  .B6122b,
  .fP222b,
  .t6612b,
  .o2221b,
  /* Bottom Sheet & Sidebars */
  #rhs,
  .ez002b,
  #sfc,
  .G6612b,
  /* Doodle Containers */
  #doodle,
  .doodle,
  #lh-doodle,
  #np-doodle {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
    pointer-events: none !important;
  }

