    font-size: 13px !important;
    color: #000000 !important;
    line-height: 1.24 !important;
  }

  /* ==========================================================================
     08. FOOTER RECREATION
     ========================================================================== */
  .K9222b,
  .p6222b,
  .fbar,
  #fbar,
